@startuml

class RepairShop {
  + Name : string
  + Address : string
}

class Repair {
  + Duration : int
  + Cost : double
}

class Vehicle {
  + LicensePlateNumber : string
  + Mileage : int
}

class Order {
  + PacketSize : int
  + Comment : string
  + StartTime : time
  + EndTime : time
  + PickUpAddress : string
  + DeliveryAddress : string
}

abstract class Employee {
  + Name : string
  + Ssn : int
}

class Driver extends Employee {}

abstract class OtherEmployee extends Employee {
  + UserName : string
  + Password : string
}

class Planner extends OtherEmployee {}

class AdministrationEmployee extends OtherEmployee {
  + FieldOfActivity : string
}

class PartnerFirm {
  + Name : string
  + Address : string
}

class Customer {
  + Name : string
  + BillingAddress : string
}

enum VehicleType {
  RefrigeratedTruck
  SmallVan
  LoadingPlatform
  BoxTruck
}

RepairShop "1" -- "*" Repair
Repair "*" -- "1" Vehicle
Repair "*" -- "1" Employee
Vehicle "*" -- "1" VehicleType
Vehicle "1" -- "*" Order
Driver "1" -- "*" Order
Planner "1" -- "*" Order : assigns
AdministrationEmployee "0..1" -- "*" Order : places
Order "*" -- "0..1" PartnerFirm : placed with
Order "*" -- "1" Customer : client
Order "*" -- "1" Driver : completed by
Order "*" -- "1" Vehicle : uses

@enduml

